{
  "title": "Potential Business Email Compromise (BEC) via Display Name Spoofing",
  "id": "example-sigma-bec-display-spoofing",
  "description": "Detect emails where the display name matches an internal executive but the From address domain differs, indicating possible spoofing used in BEC attacks.",
  "status": "experimental",
  "author": "SOC Team",
  "logsource": {
    "product": "exchange",
    "service": "mailflow"
  },
  "detection": {
    "selection": {
      "EventID": 1026,
      "SenderDomain|contains": "corp-executive.com",
      "DisplayName|contains": "CEO"
    },
    "condition": "selection and not SenderDomain|endswith '\\corp.local'"
  },
  "fields": ["Sender", "Recipient", "Subject", "ClientIP"],
  "falsepositives": ["Internal test emails"],
  "level": "high"
}

